
# --- portable paths (generated by export) -------------------------
# Everything below derives from the repo location; override with env vars
#   COMFYUI_DIR / COMFY_PYTHON / FOUNDRY_PYTHON
$FF_ROOT = if ($PSScriptRoot -and (Test-Path (Join-Path $PSScriptRoot 'app.py'))) {
    $PSScriptRoot
} else {
    Split-Path -Parent $PSScriptRoot
}
$FF_COMFY = if ($env:COMFYUI_DIR) { $env:COMFYUI_DIR } else { Join-Path (Split-Path -Parent $FF_ROOT) 'ComfyUI' }
$FF_COMFY_PY = if ($env:COMFY_PYTHON) { $env:COMFY_PYTHON } else { Join-Path $FF_COMFY 'python.exe' }
$FF_APP_PY = if ($env:FOUNDRY_PYTHON) { $env:FOUNDRY_PYTHON } else { 'python' }
$FF_LOG = Join-Path $FF_ROOT 'logs'
if (-not (Test-Path $FF_LOG)) { New-Item -ItemType Directory -Force -Path $FF_LOG | Out-Null }
# ------------------------------------------------------------------
# set_power_limit.ps1 - enforce GPU power limit (crash protection)
# Background: this server hard-hangs when GPU >= 83C (WHEA thermal protection).
# 2026-08-20 宇凯指定: 300W (higher than old 220W cap; watch temps, app auto-interrupts at 83C).
# Reboot resets to 320W, so run on every launch.
# Auto-elevates via UAC when not admin (one prompt). Never blocks the launcher.
# Usage: & (Join-Path $FF_ROOT 'scripts\set_power_limit.ps1')            (default 300W)
#        & (Join-Path $FF_ROOT 'scripts\set_power_limit.ps1') -Target 220 (back to old cap)

param([int]$Target = 300)

$ErrorActionPreference = "Continue"

# 1. Re-launch elevated if not admin
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Host "[power] not elevated, requesting admin (UAC) to set GPU power limit..."
    try {
        Start-Process -FilePath "powershell.exe" -Verb RunAs -ArgumentList "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", "`"$PSCommandPath`"", "-Target", "$Target" -WindowStyle Hidden -ErrorAction Stop
    } catch {
        Write-Host "[power] elevation denied - power limit NOT enforced (crash risk). Run this script once as admin." -ForegroundColor Red
    }
    exit 0
}

# 2. Enforce $Target on every GPU (both directions: raise or lower)
$info = nvidia-smi --query-gpu=index,power.limit --format=csv,noheader,nounits 2>$null
if (-not $info) {
    Write-Host "[power] nvidia-smi unavailable - cannot set power limit" -ForegroundColor Red
    exit 1
}
foreach ($line in $info) {
    $parts = ($line.Trim() -split ',')
    $idx = $parts[0].Trim()
    $limit = [double]$parts[1].Trim()
    if ([math]::Abs($limit - $Target) -gt 1) {
        $out = nvidia-smi -i $idx -pl $Target 2>&1 | Out-String
        if ($LASTEXITCODE -eq 0) {
            Write-Host "[power] GPU $idx power limit -> ${Target}W (was ${limit}W)" -ForegroundColor Green
        } else {
            Write-Host "[power] GPU $idx FAILED to set limit: $($out.Trim())" -ForegroundColor Red
        }
    } else {
        Write-Host "[power] GPU $idx already at ${limit}W" -ForegroundColor Green
    }
}
Write-Host "[power] done"
